// firstTrue: smallest index where the predicate holds, or n if never.
// The predicate MUST be monotone: false...false true...true.
int firstTrue(int lo, int hi, const function<bool(int)>& p) {
    int ans = hi + 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (p(mid)) { ans = mid; hi = mid - 1; }   // candidate; hunt earlier
        else          lo = mid + 1;
    }
    return ans;
}

int search(const vector<int>& a, int target) {
    int n = (int)a.size();
    int i = firstTrue(0, n - 1, [&](int m) { return a[m] >= target; });
    return (i < n && a[i] == target) ? i : -1;    // predicate found the slot; verify
}

