def first_true(lo: int, hi: int, pred) -> int:
    """Smallest index where pred holds, or hi+1 if never.
    pred MUST be monotone: false...false true...true."""
    ans = hi + 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if pred(mid):
            ans = mid           # candidate; hunt earlier
            hi = mid - 1
        else:
            lo = mid + 1
    return ans


def search(a: list[int], target: int) -> int:
    i = first_true(0, len(a) - 1, lambda m: a[m] >= target)
    return i if i < len(a) and a[i] == target else -1   # find the slot, then verify

