def upper_bound(a: list[int], x: int) -> int:
    """First index with a[i] > x."""
    lo, hi, ans = 0, len(a) - 1, len(a)
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if a[mid] > x:
            ans = mid; hi = mid - 1
        else:
            lo = mid + 1
    return ans


def search_range(a: list[int], target: int) -> tuple[int, int]:
    lb = lower_bound(a, target)
    if lb == len(a) or a[lb] != target:
        return (-1, -1)
    return (lb, upper_bound(a, target) - 1)   # ub-1 is the last equal element

