int mySqrt(int x) {
    if (x < 2) return x;                              // 0 and 1 short-circuit
    int lo = 1, hi = x / 2 + 1, ans = 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        // guard BEFORE multiplying: mid > x/mid avoids the product entirely
        if (mid <= x / mid) { ans = mid; lo = mid + 1; }
        else                  hi = mid - 1;
    }
    return ans;
}

