def my_sqrt(x: int) -> int:
    if x < 2:
        return x                          # 0 and 1 short-circuit
    lo, hi, ans = 1, x // 2 + 1, 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        # division form mirrors the C++ overflow-free guard
        if mid <= x // mid:
            ans = mid; lo = mid + 1
        else:
            hi = mid - 1
    return ans

