int findMin(const vector<int>& a) {
    int lo = 0, hi = (int)a.size() - 1;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] > a[hi])      lo = mid + 1;   // minimum is strictly right
        else if (a[mid] < a[hi]) hi = mid;       // minimum is at or left of mid
        else                     --hi;           // a[mid] == a[hi]: cannot decide
    }
    return a[lo];
}

