int singleNonDuplicate(const vector<int>& a) {
    int lo = 0, hi = (int)a.size() - 1;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        // mid^1 is mid's partner under the pairing 0-1, 2-3, 4-5, ...
        if (a[mid] == a[mid ^ 1]) lo = mid + 1;   // pairing intact: break is right
        else                      hi = mid;       // broken: answer at or left of mid
    }
    return a[lo];
}

